-- Content batch 7 (2026-10-24): eleven more customary ceremonies (adat), one
-- for every region that had none, plus Rambu Solo' and Karapan Sapi. Each
-- cites at least two different websites, all opened (see docs/adat-data.md).
-- Only drafts change. Re-running is safe.
--
-- Left out of the text because the sources disagree: the palm used for the
-- Pukul Sapu brooms, whether the Palang Pintu test is salawat or Qur'an
-- recitation, and how many days Rambu Solo' lasts.

insert into public.ceremonies as t (
  region_id, slug, name_id, name_en, summary_id, summary_en,
  timing_id, timing_en, body_id, body_en)
select r.id, x.slug, x.name_id, x.name_en, x.summary_id, x.summary_en,
  x.timing_id, x.timing_en, x.body_id, x.body_en
from (values
  ('minangkabau', 'tabuik', 'Tabuik', 'Tabuik', 'Perayaan Asyura di Pariaman, Sumatera Barat, untuk memperingati wafatnya Husein bin Ali di Karbala, dengan menara tabuik yang diarak lalu dilepas ke laut.', 'The Ashura festival of Pariaman, West Sumatra, marking the death of Husein bin Ali at Karbala, with tabuik towers paraded and then released into the sea.', 'Setiap tahun pada 1 sampai 10 Muharam. Puncak acara bisa jatuh pada 10 hingga 15 Muharam, menyesuaikan akhir pekan.', 'Every year from 1 to 10 Muharram. The main day can fall between 10 and 15 Muharram, moved to a weekend.', 'Tabuik memperingati wafatnya Husein bin Ali, cucu Nabi Muhammad, dalam Pertempuran Karbala pada 10 Muharam. Tabuik adalah menara setinggi lebih dari sepuluh meter dari kayu, bambu, dan kertas warna, berbentuk buraq (kuda bersayap berkepala manusia) yang membawa tabut atau keranda di punggungnya, dihias bunga dan ornamen. Masyarakat membuat tabuik bersama-sama. Rangkaiannya meliputi mengambil tanah, menebang batang pisang, maatam, maarak jari-jari, maarak sorban, tabuik naik pangkek, dan hoyak tabuik. Pada hari puncak, tabuik diarak dengan iringan gandang tasa ke Pantai Gandoriah, diguncang, lalu dilepas ke laut menjelang magrib. Menurut Kompas, tradisi ini dibawa pada abad ke-19 oleh pasukan Tamil dari India yang datang ke Bengkulu, lalu menyebar ke Pariaman.', 'Tabuik commemorates the death of Husein bin Ali, grandson of the Prophet Muhammad, at the Battle of Karbala on 10 Muharram. A tabuik is a tower more than ten metres tall, made of wood, bamboo and coloured paper, shaped like a buraq (a winged horse with a human head) carrying a bier on its back, and decorated with flowers and ornaments. The community builds the tabuik together. The stages include taking soil, cutting banana trunks, maatam, parading the jari-jari, parading the turban, tabuik naik pangkek and hoyak tabuik. On the main day the towers are paraded to gandang tasa drums to Gandoriah Beach, shaken, and released into the sea before the evening prayer. According to Kompas, the tradition was brought in the 19th century by Tamil troops from India who came to Bengkulu, and it then spread to Pariaman.'),
  ('bugis', 'mappacci', 'Mappacci', 'Mappacci', 'Ritual malam pacar dalam pernikahan adat Bugis: daun pacar diletakkan di tangan calon pengantin sambil didoakan, sebagai lambang kesucian.', 'The henna rite of a Bugis wedding: pacci leaves are placed on the hands of the bride or groom with prayers, as a sign of purity.', 'Sebelum akad nikah, sebagai bagian dari rangkaian pernikahan adat.', 'Before the marriage contract (akad nikah), as part of the wedding rites.', 'Nama mappacci berasal dari kata paccing, yang berarti bersih. Ritual ini bertujuan membersihkan calon pengantin dari hal-hal yang dapat menghalangi pernikahan. Daun pacar (pacci) diletakkan di tangan calon pengantin sambil didoakan, sebagai lambang kesucian dan niat baik, dan seluruh keluarga hadir untuk memberi nasihat dan doa. Sebuah kajian di Pangkep mencatat empat tahap utama: mappasili (siraman), khatam Al-Qur''an, barasanji, dan mappacci. Kajian yang sama menjelaskan makna perlengkapannya: bantal untuk saling menghargai (sipakatau) dan martabat, sarung sutra untuk harga diri dan keteguhan, daun pucuk pisang untuk kesinambungan hidup, beras untuk kemakmuran, dan lilin (sulo mattappa) untuk penerang jalan hidup.', 'The name mappacci comes from paccing, which means clean. The rite cleanses the couple of anything that could stand in the way of the marriage. Pacci (henna) leaves are placed on the hands of the bride or groom while prayers are said, as a sign of purity and good intentions, and the whole family attends to give advice and prayers. A study in Pangkep lists four main stages: mappasili (ritual bathing), completing a reading of the Qur''an, barasanji, and mappacci itself. The same study explains the items used: a pillow for mutual respect (sipakatau) and dignity, a silk sarong for self-worth and steadfastness, young banana leaves for the continuity of life, rice for prosperity, and a candle (sulo mattappa) for light on the path ahead.'),
  ('batak', 'mangongkal-holi', 'Mangongkal Holi', 'Mangongkal Holi', 'Tradisi Batak Toba menggali dan memindahkan tulang leluhur ke tugu, sebagai penghormatan dan pemersatu keluarga besar.', 'The Batak Toba tradition of digging up ancestors'' bones and moving them to a family monument, to honour them and bring the family together.', NULL, NULL, 'Mangongkal holi berarti menggali tulang. Keluarga besar, termasuk kerabat yang merantau, berkumpul untuk menggali makam leluhur dan mengambil tulang-belulangnya. Tulang dicuci dengan air, dimasukkan ke dalam peti khusus, lalu dipindahkan ke tempat yang lebih tinggi di sebuah tugu. Upacara ini disertai pesta adat. Setelahnya, tugu menjadi tempat keluarga berziarah dan berdoa. Masyarakat percaya roh leluhur melindungi yang hidup dan membawa berkat. Setiap tahapnya mencerminkan gotong royong, penghormatan kepada leluhur, dan penegasan identitas budaya. Pengaruh Kristen dan Islam turut membentuk cara pelaksanaannya kini, tetapi intinya tetap menghormati leluhur.', 'Mangongkal holi means digging up bones. The extended family, including relatives who live far away, gathers to open the ancestors'' graves and take out their bones. The bones are washed with water, placed in a special coffin and moved to a higher place in a tugu, a family monument. The ceremony includes a traditional feast. Afterwards the tugu is where the family comes to pay respects and pray. People believe ancestral spirits protect the living and bring blessings. Each stage reflects mutual cooperation, respect for ancestors and pride in cultural identity. Christian and Islamic influences shape how it is carried out today, but its core is still honouring the ancestors.'),
  ('banjar', 'baayun-maulid', 'Baayun Maulid', 'Baayun Maulid', 'Tradisi Banjar saat Maulid Nabi: anak-anak hingga orang tua diayun dalam ayunan kain sambil dilantunkan syair maulid.', 'A Banjar tradition at the Prophet''s birthday: children and adults are rocked in cloth swings while maulid poems are sung.', 'Setiap bulan Rabiul Awal, saat peringatan Maulid Nabi Muhammad.', 'Every year in Rabi''ul Awal, during the celebration of the Prophet Muhammad''s birthday.', 'Baayun maulid adalah tradisi masyarakat Banjar di Kalimantan Selatan. Peserta diayun dalam ayunan dari tapih (sarung) yang diikat dengan tali berhias, sementara syair maulid, salawat, dan zikir dilantunkan. Pesertanya anak-anak, orang dewasa, hingga lansia. Sebagian datang karena nazar dan meyakini hajatnya terkabul, dan tradisi ini dipercaya membawa berkah sebagai ungkapan syukur atas kelahiran Nabi Muhammad. Bagi anak-anak, ada harapan agar mereka tumbuh menjadi orang saleh. Tradisi ini digelar setiap tahun di masjid keramat Al Mukarramah, Banua Halat, Tapin, yang pada 2025 diikuti 3.160 orang dari beberapa provinsi, dan juga di Masjid Sultan Suriansyah, Banjarmasin.', 'Baayun maulid is a tradition of the Banjar people of South Kalimantan. Participants are rocked in swings made of a tapih (sarong) tied with decorated rope, while maulid poems, salawat and zikir are sung. They range from children to adults and the elderly. Some come because of a vow and believe their wishes are granted afterwards, and the tradition is believed to bring blessings as thanks for the Prophet Muhammad''s birth. For children, there is the hope that they grow up pious. It is held every year at the sacred Al Mukarramah mosque in Banua Halat, Tapin, where 3,160 people from several provinces took part in 2025, and also at the Sultan Suriansyah mosque in Banjarmasin.'),
  ('maluku', 'pukul-sapu', 'Pukul Sapu', 'Pukul Sapu', 'Tradisi tahunan di Negeri Mamala dan Morella, Maluku Tengah: para pria saling memukul dengan sapu lidi hingga terluka, lambang persaudaraan dan keberanian.', 'A yearly tradition in Mamala and Morella, Central Maluku: men strike each other with stick brooms until they are wounded, as a sign of brotherhood and courage.', 'Setiap 7 Syawal, hari ketujuh setelah Idulfitri.', 'Every year on 7 Syawal, the seventh day after Eid al-Fitr.', 'Pukul sapu, atau pukul manyapu, digelar di Negeri Mamala dan Morella, Kecamatan Leihitu, Maluku Tengah. Para pria saling memukulkan sapu lidi hingga tubuh mereka terluka. Tradisi ini dipandang sebagai lambang persaudaraan, keberanian, sportivitas, dan ketangguhan orang Maluku, bukan perkelahian. Di Mamala luka diobati dengan minyak Mamala, yang dipercaya menyembuhkan luka dan patah tulang; di Morella dengan getah daun jeruk. Asal-usulnya berbeda di tiap negeri. Di Mamala, tradisi ini dikaitkan dengan minyak yang dibuat Imam Tuny ketika pilar Masjid Al-Muhibbin retak. Di Morella, tradisi ini dikaitkan dengan Perang Kapahaha melawan VOC dan Kapitan Tulukabessy. Acaranya juga diiringi tarian dan atraksi seperti bambu gila.', 'Pukul sapu, or pukul manyapu, is held in Mamala and Morella, in Leihitu, Central Maluku. Men strike each other with stick brooms until their bodies are wounded. It is seen as a sign of brotherhood, courage, sportsmanship and the resilience of the Maluku people, not as a fight. In Mamala the wounds are treated with Mamala oil, believed to heal wounds and broken bones; in Morella, with citrus leaf sap. Each village tells a different origin. In Mamala it is linked to the oil Imam Tuny made when a pillar of the Al-Muhibbin mosque cracked. In Morella it is linked to the Kapahaha War against the VOC and Kapitan Tulukabessy. Dances and shows such as bambu gila accompany it.'),
  ('sasak', 'bau-nyale', 'Bau Nyale', 'Bau Nyale', 'Tradisi suku Sasak menangkap cacing laut nyale di pantai selatan Lombok, yang dipercaya sebagai jelmaan Putri Mandalika.', 'The Sasak tradition of catching nyale sea worms on Lombok''s south coast, believed to be the reincarnation of Princess Mandalika.', 'Setiap tahun pada hari ke-20 bulan ke-10 penanggalan Sasak, biasanya sekitar Februari. Warga turun ke pantai pada dini hari.', 'Every year on the 20th day of the 10th month of the Sasak calendar, usually around February. People go down to the beach in the early morning.', 'Dalam bahasa Sasak, bau berarti menangkap, dan nyale adalah cacing laut berwarna-warni yang hanya muncul setahun sekali di tempat tertentu. Warga berkumpul di pantai selatan Lombok, terutama Pantai Seger dan Kuta Mandalika, dan menangkap nyale dengan jaring atau tangan. Menurut legenda, Putri Mandalika dilamar banyak pangeran. Untuk mencegah pertumpahan darah, ia menceburkan diri ke laut, lalu muncul banyak cacing yang dipercaya sebagai jelmaannya. Nyale dipercaya membawa kemakmuran bagi yang menghargainya. Tangkapan yang banyak dianggap pertanda panen yang baik, sehingga daun pembungkus nyale ditebar ke sawah. Kini pemerintah daerah juga menggelar festival di sekitar acara ini.', 'In Sasak, bau means to catch, and nyale are colourful sea worms that appear only once a year in certain places. People gather on Lombok''s south coast, especially Seger and Kuta Mandalika beaches, and catch the worms with nets or by hand. In the legend, Princess Mandalika was courted by many princes. To prevent bloodshed she threw herself into the sea, and many worms appeared, believed to be her reincarnation. The nyale are believed to bring prosperity to those who respect them. A big catch is a sign of a good harvest, so the leaves used to wrap the worms are scattered over the rice fields. Today the local government also holds a festival around it.'),
  ('betawi', 'palang-pintu', 'Palang Pintu', 'Palang Pintu', 'Tradisi pernikahan Betawi: rombongan pengantin pria dihadang di rumah pengantin wanita dan harus melewati adu pantun dan silat.', 'A Betawi wedding tradition: the groom''s party is stopped at the bride''s house and must win an exchange of pantun and a silat bout.', 'Saat rombongan pengantin pria tiba di rumah pengantin wanita, dalam rangkaian pernikahan adat.', 'When the groom''s party arrives at the bride''s house, as part of the wedding.', 'Palang pintu berasal dari kata palang (penghalang) dan pintu. Saat rombongan pengantin pria hendak masuk, perwakilan pihak perempuan menghadang mereka. Kedua pihak diwakili tukang pantun dan jagoan silat. Mereka saling berbalas pantun yang sering lucu, lalu beradu silat, dan kemenangan jagoan pihak pria menandai runtuhnya penghalang. Pihak pria juga diminta membawakan bacaan agama sebelum dipersilakan masuk. Tradisi ini melambangkan perlindungan orang tua kepada putrinya, kesungguhan pengantin pria memikul tanggung jawab rumah tangga, dan penerimaan antara dua keluarga. Tujuannya suasana gembira, bukan ketegangan.', 'Palang pintu joins palang, a barrier, and pintu, a door. When the groom''s party is about to enter, representatives of the bride''s side block the way. Each side is represented by a pantun speaker and a silat champion. They trade pantun, often humorous ones, then fight a silat bout, and the win of the groom''s champion marks the barrier coming down. The groom''s side is also asked for a religious recitation before being invited in. The tradition stands for parents protecting their daughter, the groom''s readiness to take on a household, and the two families accepting each other. Its aim is joy, not tension.'),
  ('aceh', 'peusijuek', 'Peusijuek', 'Peusijuek', 'Tradisi Aceh untuk mendinginkan dan memberkati orang atau benda: syukur kepada Allah dan doa keselamatan, juga untuk berdamai.', 'The Acehnese rite of cooling and blessing a person or thing: thanks to God and a prayer for safety, also used to make peace.', 'Pada peristiwa penting: pernikahan, keberangkatan dan kepulangan haji, membuka usaha, menyambut tamu atau pejabat, setelah meraih keberhasilan, dan setelah berdamai.', 'At important moments: weddings, leaving for and returning from the hajj, opening a business, welcoming guests or officials, after an achievement, and after a reconciliation.', 'Peusijuek berarti mendinginkan atau menenangkan hati, dan dekat dengan tradisi tepung tawar. Upacara ini dipimpin tokoh agama atau tetua adat yang dihormati, misalnya seorang teungku. Prosesi dimulai dengan basmalah, salawat, dan doa. Beras padi ditaburkan, air tepung tawar dipercikkan dengan tumbuhan hijau, dan nasi ketan diberikan, lalu upacara ditutup dengan doa. Air dan tumbuhan hijau dimaknai sebagai penyejuk, beras padi sebagai sumber kehidupan, dan nasi ketan sebagai perekat antarsesama. Peusijuek juga dipakai untuk meredakan ketegangan setelah perselisihan kecil, agar kedua pihak saling memaafkan dan menyambung silaturahmi. Tata caranya berbeda di tiap daerah.', 'Peusijuek means to cool or calm the heart, and it is close to the Malay tepung tawar. A respected religious or customary leader, such as a teungku, leads it. It opens with the basmalah, salawat and a prayer. Rice grains are scattered, tepung tawar water is sprinkled with green plants, and glutinous rice is given, then it closes with a prayer. Water and green plants stand for cooling, rice for the source of life, and glutinous rice for the bond between people. Peusijuek is also used to cool tensions after minor disputes, so that both sides forgive each other and restore their ties. The steps differ from region to region.'),
  ('rote', 'caci', 'Caci', 'Caci', 'Tarian adu cambuk masyarakat Manggarai di Flores barat, digelar saat pesta panen Penti sebagai ungkapan syukur.', 'The whip-duel dance of the Manggarai people of western Flores, held at the Penti harvest festival as a thanksgiving.', 'Terutama saat pesta panen Penti, juga pada pernikahan dan upacara adat lain.', 'Mainly at the Penti harvest festival, and also at weddings and other ceremonies.', 'Caci adalah adu cambuk antara dua laki-laki Manggarai yang bergantian menjadi penyerang dan bertahan. Penyerang memakai cambuk rotan, dan yang bertahan menangkis dengan perisai dari kulit kerbau. Para petarung bertelanjang dada, memakai kain songket, dan mengenakan topeng atau penutup kepala dari kulit kerbau. Namanya dikaitkan dengan kata Manggarai yang berarti satu dan uji, yaitu uji satu lawan satu. Caci bermula sebagai bagian dari ritual panen dan kesuburan tanah: ungkapan syukur kepada Yang Mahakuasa dan leluhur atas tanah yang subur, hujan, dan panen. Caci juga melambangkan keberanian, sportivitas, dan persatuan, serta menjadi tanda kedewasaan bagi pemuda. Kini caci juga ditampilkan di Ruteng dan Labuan Bajo.', 'Caci is a whip duel between two Manggarai men, who take turns attacking and defending. The attacker uses a rattan whip, and the defender blocks with a buffalo-hide shield. The fighters are bare-chested, wear songket cloth, and wear masks or headgear of buffalo hide. The name is linked to Manggarai words for one and test: a one-on-one test. Caci began as part of the harvest and fertility ritual, a thanksgiving to the gods and ancestors for fertile land, rain and harvest. It also stands for courage, sportsmanship and unity, and marks a rite of passage for young men. Today it is also performed in Ruteng and Labuan Bajo.'),
  ('toraja', 'rambu-solo', 'Rambu Solo''', 'Rambu Solo''', 'Upacara pemakaman adat Toraja, penghormatan terakhir keluarga yang mengantar roh ke alam baka, dengan kurban kerbau.', 'The Toraja funeral ceremony, the family''s last tribute that sends the spirit to the afterlife, with the sacrifice of buffalo.', 'Setelah keluarga siap, kadang bertahun-tahun setelah kematian. Upacaranya berlangsung beberapa hari.', 'Once the family is ready, sometimes years after the death. The ceremony lasts several days.', 'Rambu solo'' secara harfiah berarti asap yang turun, karena ritusnya digelar setelah tengah hari saat matahari turun. Keluarga wajib menggelarnya sebagai penghormatan terakhir, dan sering menabung bertahun-tahun untuk itu. Bentuk upacaranya mengikuti status sosial almarhum, dari yang paling sederhana hingga rampasan untuk bangsawan tinggi. Rangkaiannya meliputi musyawarah keluarga, pembangunan pondok upacara, penyembelihan kerbau dan babi, upacara utama, lalu arak-arakan peti jenazah ke tempat peristirahatan terakhir di tebing atau gua. Kerbau dipercaya mengantar roh ke Puya, alam arwah, dan jumlahnya bergantung pada status sosial. Kerabat juga menyumbang kerbau atau babi sebagai tanda duka. Ada pula tarian, ma''badong (nyanyian duka yang dilantunkan dalam lingkaran), dan ma''pasilaga tedong (adu kerbau).', 'Rambu solo'' literally means smoke going down, because its rites are held after noon, as the sun descends. The family is bound to hold it as a last tribute and often saves for years to do so. Its form follows the social status of the deceased, from the simplest rites up to rampasan for the high nobility. The stages include a family meeting, building ceremonial huts, the sacrifice of buffalo and pigs, the main ceremony, and a procession carrying the coffin to its resting place in a cliff or cave. The buffalo is believed to guide the spirit to Puya, the land of souls, and the number of animals depends on social status. Relatives also give buffalo or pigs as a sign of sympathy. There are dances, ma''badong (a funeral chant sung in a circle) and ma''pasilaga tedong (buffalo fights).'),
  ('jawa', 'karapan-sapi', 'Karapan Sapi', 'Karapan Sapi', 'Lomba pacu sapi tradisional di Pulau Madura, Jawa Timur, yang bermula sebagai perayaan panen.', 'The traditional bull race of Madura island, East Java, which began as a harvest celebration.', 'Setiap tahun, sekitar Juli hingga Oktober, dengan lomba piala besar di Pamekasan.', 'Every year, around July to October, with the main trophy race in Pamekasan.', 'Karapan sapi bermula sebagai cara merayakan panen yang melimpah, karena sapi dipakai untuk membajak sawah. Sepasang sapi jantan dipasang pada sebatang kayu dan dipacu di lintasan sekitar 130 meter, mirip balap kereta. Pemenangnya pasangan sapi yang pertama mencapai garis akhir. Sapi dihias, lomba diiringi gamelan, dan acaranya menandai akhir panen tembakau dan padi. Sapi pemenang bisa menjadi pejantan dan mengangkat nama serta status sosial pemiliknya. Asal namanya belum pasti. Cara memacu sapi yang melukai hewan juga menuai kritik, berbeda dengan sapi sonok, yang menilai keindahan langkah sapi betina.', 'Karapan sapi began as a way to celebrate a good harvest, since cattle were used to plough the fields. A pair of bulls is yoked to a length of wood and raced over about 130 metres, like a chariot race. The winner is the pair that reaches the finish line first. The bulls are decorated, gamelan music accompanies the race, and it marks the end of the tobacco and rice harvests. Winning bulls can become breeding stock and raise their owner''s name and standing. The origin of the name is uncertain. Methods that hurt the bulls to make them run have drawn criticism, unlike sapi sonok, where cows are judged on the beauty of their walk.')
) as x (region, slug, name_id, name_en, summary_id, summary_en, timing_id, timing_en, body_id, body_en)
join public.regions r on r.slug = x.region
on conflict (slug) do update set
  region_id = excluded.region_id, name_id = excluded.name_id, name_en = excluded.name_en,
  summary_id = excluded.summary_id, summary_en = excluded.summary_en,
  timing_id = excluded.timing_id, timing_en = excluded.timing_en,
  body_id = excluded.body_id, body_en = excluded.body_en
where t.review_status = 'draft';

create temporary table batch_sources (slug text, title text, url text, credit text) on commit drop;
insert into batch_sources values
  ('tabuik', 'Tabuik Pariaman, Harmoni Agama dan Budaya', 'https://www.goodnewsfromindonesia.id/2023/10/16/tabuik-pariaman-harmoni-agama-dan-budaya', 'Irwandi, Good News From Indonesia, 16 October 2023'),
  ('tabuik', 'Mengenal Tabuik: Asal-usul dan Tahapan', 'https://regional.kompas.com/read/2022/09/09/221047378/mengenal-tabuik-asal-usul-dan-tahapan?page=all', 'Dini Daniswari, Kompas.com, 9 September 2022'),
  ('tabuik', 'Pesona Budaya Hoyak Tabuik Piaman', 'https://www.indonesia.travel/id-id/events/event-detail/pesona-budaya-hoyak-tabuik-piaman-2026/', 'Kementerian Pariwisata RI (indonesia.travel)'),
  ('mappacci', 'Makna Simbolik Prosesi Mapacci pada Pernikahan Adat Bugis Pangkep di Kelurahan Pa''bundukang Kabupaten Pangkep', 'https://ojs.unm.ac.id/Panrita-bsdp/article/view/36327', 'R. H. Arifin, M. Saleh and Hajrah, Panrita (Universitas Negeri Makassar), 2022'),
  ('mappacci', 'Apa Itu Tradisi Mappacci? Feby Putri Jalani Ritual Adat Bugis dengan Haru Jelang Nikah', 'https://www.kompas.com/sulawesi-selatan/read/2025/09/15/183000788/apa-itu-tradisi-mappacci-feby-putri-jalani-ritual-adat-bugis', 'Kompas.com, 15 September 2025'),
  ('mangongkal-holi', 'Mangongkal Holi, Tradisi Sakral Menggali Tulang Leluhur oleh Etnis Batak Toba', 'https://www.goodnewsfromindonesia.id/2024/11/19/mangongkal-holi-tradisi-sakral-menggali-tulang-leluhur-oleh-etnis-batak-toba', 'Lowry Sianturi, Good News From Indonesia, 19 November 2024'),
  ('mangongkal-holi', 'Mangongkal Holi dalam Etnik Batak Toba: Kajian Wacana Struktural', 'https://jptam.org/index.php/jptam/article/view/15497', 'Sinulingga, Sianipar and Harniko, Jurnal Pendidikan Tambusai, 2024'),
  ('baayun-maulid', 'Banjarmasin gelar tradisi Baayun Maulid', 'https://kalsel.antaranews.com/berita/388674/banjarmasin-gelar-tradisi-baayun-maulid', 'Sukarli, ANTARA Kalsel, 27 September 2023'),
  ('baayun-maulid', '3.160 Jemaah Ikuti Tradisi Baayun Maulid di Masjid Keramat Banua Halat Tapin', 'https://www.goodnewsfromindonesia.id/2025/09/08/3160-jemaah-ikuti-tradisi-baayun-maulid-di-masjid-keramat-banua-halat-tapin', 'KALSELMAJU.COM via Good News From Indonesia, 8 September 2025'),
